<?php
// Comment edit page: allow the comment author to revise their note and record its edited timestamp.
require_once __DIR__.'/helpers.php';require_login();$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT);$q=$pdo->prepare('SELECT * FROM comments WHERE id=? AND user_id=?');$q->execute([$id,(int)$_SESSION['user']['id']]);$comment=$q->fetch();if(!$comment){http_response_code(404);exit('Comment not found or you do not own it.');}$error='';$body=$comment['body'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$body=trim((string)($_POST['body']??''));if(mb_strlen($body)<2||mb_strlen($body)>1000)$error='Comment must be 2–1,000 characters.';else{$q=$pdo->prepare('UPDATE comments SET body=?,edited_at=NOW() WHERE id=? AND user_id=?');$q->execute([$body,$id,(int)$_SESSION['user']['id']]);header('Location: recipe.php?id='.(int)$comment['recipe_id'].'#comments');exit;}}$pageTitle='Edit comment';require __DIR__.'/header.php';?>
<section class="form-page"><a class="back-link" href="recipe.php?id=<?= (int)$comment['recipe_id'] ?>#comments">← Back to recipe</a><p class="eyebrow">A QUICK TIDY-UP</p><h1>Edit your note.</h1><?php if($error): ?><div class="form-errors"><p><?= h($error) ?></p></div><?php endif; ?><form method="post" class="stack-form narrow-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><label>Your comment<textarea name="body" required minlength="2" maxlength="1000" rows="6"><?= h($body) ?></textarea></label><button class="button button-dark">Save changes →</button></form></section><?php require __DIR__.'/footer.php';?>
